import {api} from './auth.js';
import {bankLogo} from './finance-bank-header.js';
import {upgradeCashback,compareBanks} from './cashback-model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function startCashback(root,user){
 const style=document.createElement('link');style.rel='stylesheet';style.href='/finance.css';document.head.append(style);
 const loaded=await api('/api/cashback');let data=upgradeCashback(loaded.data),revision=loaded.revision;
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Novosibirsk',year:'numeric',month:'2-digit'}).formatToParts(new Date());
 let period=parts.find(p=>p.type==='year').value+'-'+parts.find(p=>p.type==='month').value,timer,busy=false,pending=false,dirty=false,failed=false,view='categories';
 const monthNames=Array.from({length:12},(_,i)=>new Date(2026,i,1).toLocaleDateString('ru-RU',{month:'long'}));
 const entries=()=>data.months[period]||{};
 function status(text){root.querySelector('#cashback-status').textContent=text;root.querySelector('#cashback-retry').hidden=!failed;}
 const recordedNames=()=>Object.values(data.months).flatMap(m=>Object.values(m).flatMap(rows=>rows.map(r=>r.name.trim()).filter(Boolean)));
 function cleanCategories(){const used=new Set(recordedNames().map(n=>n.toLocaleLowerCase('ru'))),names=[...new Set(data.categories.map(n=>n.trim()).filter(Boolean))];data.categories=names.filter(n=>used.has(n.toLocaleLowerCase('ru'))||!names.some(other=>other.length>n.length&&other.toLocaleLowerCase('ru').startsWith(n.toLocaleLowerCase('ru')))).sort((a,b)=>a.localeCompare(b,'ru'));}
 function history(){return data.categories;}
 function suggestions(){root.querySelector('#cashback-categories').innerHTML=history().map(c=>`<option value="${esc(c)}"></option>`).join('');}
 function remember(name){if(!name?.trim())return;data.categories=[...new Set([...data.categories,name.trim()])];cleanCategories();}
 const oldCategories=JSON.stringify(data.categories);data.categories=[...new Set([...data.categories,...recordedNames()])];cleanCategories();dirty=oldCategories!==JSON.stringify(data.categories);
 function sortCards(){const grid=root.querySelector('#cashback-cards');if(grid?.contains(document.activeElement))return;if(grid)data.banks.filter(b=>!b.hidden).sort((a,b)=>compareBanks(a,b,entries())).forEach(b=>{const card=[...grid.children].find(e=>e.dataset.bank===b.id);if(card)grid.append(card);});}
 function valid(){return data.banks.every(b=>b.name.trim())&&Object.values(data.months).every(m=>Object.values(m).every(rows=>rows.every(r=>r.percent===null||Number.isFinite(r.percent)&&r.percent>=0&&r.percent<=100)));}
 function changed(){dirty=true;failed=false;status(valid()?'Сохранение…':'Укажите название банка и процент от 0 до 100.');clearTimeout(timer);timer=setTimeout(save,650);}
 async function save(){clearTimeout(timer);if(busy){pending=true;return;}if(!dirty)return;if(!valid()){status('Укажите название банка и процент от 0 до 100.');return;}busy=true;pending=false;failed=false;status('Сохранение…');const snapshot=structuredClone(data);
  try{const result=await api('/api/cashback',{method:'PUT',body:JSON.stringify({revision,data:snapshot})});revision=result.revision;dirty=JSON.stringify(data)!==JSON.stringify(snapshot);status(dirty?'Сохранение…':'Все изменения сохранены');}
  catch(e){failed=true;status(e.message+' Введённые данные остаются на экране.');}
  finally{busy=false;if(!failed&&(pending||dirty))save();}
 }
 const rowsFor=id=>{data.months[period]??={};return data.months[period][id]??=[];};
 function card(b){const rows=entries()[b.id]||[];return `<section class="panel cashback-card" data-bank="${b.id}"><h2 class="cashback-bank-title">${bankLogo(b.logo)}<span>${esc(b.name)}</span></h2><table class="cashback-rows"><thead><tr><th>Категория</th><th>%</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr data-index="${i}"><td><input data-category maxlength="150" list="cashback-categories" value="${esc(r.name)}" placeholder="Название категории" aria-label="Категория ${esc(b.name)}"></td><td><input data-percent type="number" min="0" max="100" step="0.01" value="${r.percent??''}" aria-label="Процент ${esc(b.name)}"></td><td><button data-remove="${i}" aria-label="Удалить категорию">×</button></td></tr>`).join('')}</tbody></table><button data-add-row>＋ Категория</button></section>`;}
 function settings(){return `<div class="row between"><h2>Банки</h2><button id="cashback-add-bank" class="primary">＋ Банк</button></div><div id="cashback-bank-settings">${data.banks.map(b=>`<fieldset class="settings-block" data-bank="${b.id}"><legend>${esc(b.name)||'Новый банк'}</legend><label class="field">Название<input data-bank-name maxlength="100" value="${esc(b.name)}"></label><label class="field">Логотип<select data-logo>${[['sber','Сбер'],['t','Т-Банк'],['alfa','Альфа-Банк'],['ozon','OZON Банк'],['gazprom','Газпромбанк'],['vtb','ВТБ'],['yandex','Яндекс'],['generic','Другой банк']].map(([k,l])=>`<option value="${k}" ${b.logo===k?'selected':''}>${l}</option>`).join('')}</select></label><label><input data-visible type="checkbox" ${b.hidden?'':'checked'}> Показывать в списке</label></fieldset>`).join('')}</div>`;}
 function render(){const years=[...new Set([Number(period.slice(0,4)),Number(parts.find(p=>p.type==='year').value),...Object.keys(data.months).map(m=>Number(m.slice(0,4)))])].sort((a,b)=>b-a);
 root.innerHTML=`<header class="topbar"><a class="brand" href="/" style="text-decoration:none;color:inherit">Свои деньги<em>.</em></a><button id="cashback-logout">Выйти</button></header><main class="portal"><p class="muted">Выбранные категории банков</p><h1>Кэшбэки</h1><nav class="fin-nav"><button data-view="categories" class="${view==='categories'?'selected':''}">Категории</button><button data-view="banks" class="${view==='banks'?'selected':''}">Настройки банков</button></nav><div class="row cashback-filters"><label class="fin-filter">Год<select id="cashback-year">${years.map(y=>`<option ${y===Number(period.slice(0,4))?'selected':''}>${y}</option>`).join('')}</select></label><label class="fin-filter">Месяц<select id="cashback-month">${monthNames.map((m,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${i+1===Number(period.slice(5))?'selected':''}>${m}</option>`).join('')}</select></label><button id="cashback-prev">← Предыдущий месяц</button><button id="cashback-next">Следующий месяц →</button></div><p id="cashback-status" role="status">${busy?'Сохранение…':dirty?'Есть несохранённые изменения':'Все изменения сохранены'}</p><button id="cashback-retry" hidden>Повторить сохранение</button><datalist id="cashback-categories"></datalist>${view==='banks'?settings():`<div id="cashback-cards">${data.banks.filter(b=>!b.hidden).sort((a,b)=>compareBanks(a,b,entries())).map(card).join('')}</div>${data.banks.every(b=>b.hidden)?'<p>Все банки скрыты. Включите их в настройках банков.</p>':''}`}<p><button id="cashback-export">Скачать резервную копию</button></p></main>`;
 suggestions();
 root.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>{if(!valid()||failed)return;save();view=e.dataset.view;render();});
 root.querySelectorAll('.cashback-card').forEach(c=>{c.addEventListener('input',e=>{const row=e.target.closest('[data-index]');if(!row)return;const r=rowsFor(c.dataset.bank)[Number(row.dataset.index)];if(e.target.matches('[data-category]'))r.name=e.target.value;else if(e.target.matches('[data-percent]'))r.percent=e.target.value===''?null:Number(e.target.value);changed();});c.addEventListener('focusout',e=>{if(e.target.matches('[data-category]')){remember(e.target.value);changed();}suggestions();setTimeout(()=>{if(!c.contains(document.activeElement))sortCards();},0);});c.querySelector('[data-add-row]').onclick=()=>{rowsFor(c.dataset.bank).push({name:'',percent:null});changed();render();const next=root.querySelector(`[data-bank="${c.dataset.bank}"] tbody tr:last-child input`);next?.focus();};c.querySelectorAll('[data-remove]').forEach(e=>e.onclick=()=>{rowsFor(c.dataset.bank).splice(Number(e.dataset.remove),1);changed();render();});});
 root.querySelectorAll('#cashback-bank-settings [data-bank]').forEach(f=>{const b=data.banks.find(b=>b.id===f.dataset.bank);f.querySelector('[data-bank-name]').oninput=e=>{b.name=e.target.value;f.querySelector('legend').textContent=b.name||'Новый банк';changed();};f.querySelector('[data-logo]').onchange=e=>{b.logo=e.target.value;changed();};f.querySelector('[data-visible]').onchange=e=>{b.hidden=!e.target.checked;changed();};});
 root.querySelector('#cashback-add-bank')?.addEventListener('click',()=>{if(!valid())return;const b={id:crypto.randomUUID(),name:'Новый банк',logo:'generic',hidden:false};data.banks.push(b);changed();render();root.querySelector(`[data-bank="${b.id}"] [data-bank-name]`).focus();});
 const change=next=>{if(failed||!valid()){status('Сначала исправьте поля и сохраните изменения или скачайте резервную копию.');return;}save();period=next;render();};
 root.querySelector('#cashback-year').onchange=e=>change(e.target.value+period.slice(4));root.querySelector('#cashback-month').onchange=e=>change(period.slice(0,5)+e.target.value);
 for(const [id,delta] of [['prev',-1],['next',1]])root.querySelector('#cashback-'+id).onclick=()=>{const d=new Date(Number(period.slice(0,4)),Number(period.slice(5))-1+delta,1);if(d.getFullYear()<2000||d.getFullYear()>2099)return;change(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'));};
 root.querySelector('#cashback-retry').onclick=save;
 root.querySelector('#cashback-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({format:'money-cashback-backup-v2',data},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='cashback-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 root.querySelector('#cashback-logout').onclick=async()=>{if(dirty||busy){status('Дождитесь сохранения данных перед выходом.');return;}await api('/api/auth/logout',{method:'POST',body:'{}'});location.href='/';};
 }
 window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});render();if(dirty)timer=setTimeout(save,650);
}
